import static org.junit.Assert.*;

public class MutableDateTime_addDays_TriageGen2Test {

    @Test
    public void testAddDays_WithPositiveDays() {
        // Arrange: Set a fixed date (2023-01-01)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        int daysToAdd = 5;

        // Act
        dt.addDays(daysToAdd);

        // Assert: Should be 2023-01-06
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(6, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_WithNegativeDays() {
        // Arrange: Set a fixed date (2023-01-10)
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        int daysToAdd = -3;

        // Act
        dt.addDays(daysToAdd);

        // Assert: Should be 2023-01-07
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(7, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_WithZeroDays() {
        // Arrange: Set a fixed date
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int daysToAdd = 0;

        // Act
        dt.addDays(daysToAdd);

        // Assert: Date should remain unchanged
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_WithOneDay() {
        // This tests the specific branch: if (days != 1)
        // When days == 1, the code inside the 'if' block should NOT execute.
        // While the result of adding 1 day is mathematically the same via the chronology,
        // the logic explicitly bypasses the setMillis call.

        // Arrange
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int daysToAdd = 1;

        // Act
        dt.addDays(daysToAdd);

        // Assert: The instant should remain exactly the same because the logic skips the addition
        // Note: Based on the provided implementation: if (days != 1) { add } 
        // If days is 1, it does nothing. This is likely a specific behavior/bug in the provided snippet,
        // but for unit testing purposes, we test the code as written.
        assertEquals("When days is 1, the implementation skips the addition logic", originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_CrossingMonthBoundary() {
        // Arrange: Last day of January
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 12, 0, 0, 0);
        int daysToAdd = 2;

        // Act
        dt.addDays(daysToAdd);

        // Assert: Should be Feb 2nd
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(2, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_CrossingLeapYearBoundary() {
        // Arrange: Feb 28 in a leap year
        MutableDateTime dt = new MutableDateTime(2024, 2, 28, 12, 0, 0, 0);
        int daysToAdd = 2;

        // Act
        dt.addDays(daysToAdd);

        // Assert: Should be March 1st (2024 is leap year, so Feb 29 exists)
        assertEquals(2024, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }
}
